 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_efCpCpnIntRt_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_efCpCpnIntRt_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await $c.win.alert('이미 상장되어 있는 채권입니다.')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10801.ipt_efCpCpnIntRt_onclick' }); }
};

