/**
 * @method
 * @name scwin.setCpIsuNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm idx
 * @returns
 * @hidden N
*/
scwin.setCpIsuNm = async function (fm, idx) {
    /* sdd-asis-lifecycle:begin setCpIsuNm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) > 0 && $c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) != 6) {
        await $c.win.alert("표면이자율 입력시\n입력예에 따라 소수점 포함해서 6자리[예:09.090]로 입력바랍니다.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if ($c.num.isNumber(fm["ef_cp_cpn_int_rt"+idx])) {
        if ($c.str.getByteLength(fm["ef_cp_cpn_int_rt"+idx].value) != 0) {
            fm["ef_cp_isu_nm"+idx].value = '국고채이자 ' + Del_Point2(fm["ef_cp_cpn_int_rt"+idx]) + '-' + fm["ef_cp_rdmp_dt"+idx].value.substring(2, 6);
            fm["ef_fisn_val"+idx].value = 'KTB/Disc STRIPS IR ' + fm["ef_cp_rdmp_dt"+idx].value + ' Sr Gtd';
        } else {
            fm["ef_cp_isu_nm"+idx].value = '';
            fm["ef_fisn_val"+idx].value = '';
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setParSumAmt
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm idx rows
 * @returns
 * @hidden N
*/
scwin.setParSumAmt = function (fm, idx, rows) {
    /* sdd-asis-lifecycle:begin setParSumAmt — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.str.getByteLength(fm["ef_cp_par_tot_amt"+idx].value) > 0) {
        $c.num.formatNumber(fm["ef_cp_par_tot_amt"+idx]);
        for (idx1 = idx; idx1 < rows; idx1++) {
            fm["ef_cp_par_tot_amt"+idx1].value = fm["ef_cp_par_tot_amt"+idx].value;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.CheckValues
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm rows
 * @returns
 * @hidden N
*/
scwin.CheckValues = async function (fm, rows) {
    /* sdd-asis-lifecycle:begin CheckValues — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await scwin.SendCheckData(fm, rows)) {
        for (idx = 0; idx < rows; idx++) {
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_rdmp_dt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_rdmp_dt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_cpn_int_rt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_cpn_int_rt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_par_tot_amt' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_par_tot_amt' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(String('input[name=ef_cp_isu_nm' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_cp_isu_nm' + idx + ']').val());
            (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).getComponentById(String('input[name=ef_fisn_val' + idx + ']').replace(/^#/, ''))) || { setValue: function () {} }).setValue($('input[name=ef_fisn_val' + idx + ']').val());
        }
        $c.win.closePopup();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.SendCheckData
 * @author Inswave
 * @date 2026. 09. 29
 * @param fm rows
 * @returns
 * @hidden N
*/
scwin.SendCheckData = async function (fm, rows) {
    /* sdd-asis-lifecycle:begin SendCheckData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (idx = 0; idx < rows; idx++) {
        if ($c.str.getByteLength($('input[name=ef_cp_cpn_int_rt' + idx + ']').val()) == 0) {
            await $c.win.alert((idx + 1) + "번째 열의 표면이자율을 입력하십시오.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
        if ($c.str.getByteLength($('input[name=ef_cp_par_tot_amt' + idx + ']').val()) == 0) {
            await $c.win.alert((idx + 1) + "번째 열의 액면총액을 입력하십시오.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.winClose
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.winClose = function () {
    /* sdd-asis-lifecycle:begin winClose — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
